  const { eroeffnen, behalten, schliessen } = gleicheAb(e.offene ?? [], e.nachforderungen ?? [], jetzt);
  return { json: { akte_id: e.akte_id, pruefung_id: e.pruefung_id ?? null, fristen: e.fristen ?? {}, jetzt, phase: 'abgleichen', eroeffnen, behalten, schliessen } };
});

// Transport: je fälligem Versand ein Item für den Mail-Node. Text, Betreff
// und Empfänger kommen fertig aus src/ (Versand planen); hier wird nur
// aufgeteilt. Nichts fällig, keine Items, kein Versand.
const aus = [];
for (const item of $input.all()) {
  const e = item.json;
  for (const f of e.versenden ?? []) {
    aus.push({ json: {
      akte_id: e.akte_id, jetzt: e.jetzt, request_case_id: f.id, grund: f.grund, feld: f.feld,
      stufe: f.versand.stufe, an: (f.versand.an ?? []).join(','), rollen: (f.versand.rollen ?? []).join(', '),
      betreff: f.versand.betreff, text: f.versand.text,
    } });
  }
}
return aus;
